```c
#include <stdio.h>

#define N 5

struct Producto {
    int codigo;
    char nombre[50];
    float precio;
};

void imprimirCatalogo(struct Producto cat[], int n) {
    for (int i = 0; i < n; i++) {
        printf("[%d] %s - $%.2f\n", cat[i].codigo, cat[i].nombre, cat[i].precio);
    }
}

int main() {
    struct Producto catalogo[N] = {
        {103, "Borrador",  0.80},
        {101, "Lapicero",  1.50},
        {104, "Regla",     2.00},
        {105, "Mochila",  25.00},
        {102, "Cuaderno",  3.75}
    };

    printf("Antes de ordenar:\n");
    imprimirCatalogo(catalogo, N);

    /* Bubble sort por precio ascendente */
    for (int i = 0; i < N - 1; i++) {
        for (int j = 0; j < N - 1 - i; j++) {
            if (catalogo[j].precio > catalogo[j+1].precio) {
                struct Producto temp = catalogo[j];
                catalogo[j]         = catalogo[j+1];
                catalogo[j+1]       = temp;
            }
        }
    }

    printf("\nDespués de ordenar:\n");
    imprimirCatalogo(catalogo, N);

    return 0;
}
```

